package main

import (
	"fmt"
	"strings"
)

func route(kind, binding, key string, headers map[string]string) bool {
	switch kind {
	case "direct":
		return binding == key
	case "fanout":
		return true
	case "topic":
		b, k := strings.Split(binding, "."), strings.Split(key, ".")
		return len(b) == len(k) && (b[0] == "*" || b[0] == k[0]) && (b[1] == "*" || b[1] == k[1])
	case "headers":
		parts := strings.SplitN(binding, "=", 2)
		return len(parts) == 2 && headers[parts[0]] == parts[1]
	}
	return false
}

func main() {
	h := map[string]string{"format": "pdf"}
	fmt.Printf("direct=%v fanout=%v topic=%v headers=%v\n", route("direct", "order.created", "order.created", nil), route("fanout", "", "anything", nil), route("topic", "logs.*", "logs.error", nil), route("headers", "format=pdf", "", h))
}

