package main

import (
	"fmt"
	"strings"
)

func match(pattern, key string) bool {
	p, k := strings.Split(pattern, "."), strings.Split(key, ".")
	var walk func(int, int) bool
	walk = func(i, j int) bool {
		if i == len(p) { return j == len(k) }
		if p[i] == "#" {
			if walk(i+1, j) { return true }
			return j < len(k) && walk(i, j+1)
		}
		return j < len(k) && (p[i] == "*" || p[i] == k[j]) && walk(i+1, j+1)
	}
	return walk(0, 0)
}

func main() {
	fmt.Println(match("logs.*", "logs.error"), match("audit.#", "audit.user.created"), match("logs.*", "logs.api.error"))
}

